PUT kanmaster
{
  "mappings": {
    "properties": {
      "district": { "type": "keyword" },
      "localbody_type": { "type": "keyword" },            // e.g. Municipality, Panchayat, Corporation
      "localbody_id": { "type": "keyword" },              // unique local body code (like G04001)
      "localbody_name": { "type": "keyword" },            // local body name
      "wards": {
        "type": "nested",
        "properties": {
          "ward_no": { "type": "keyword" },
          "ward_name": { 
            "type": "text",
            "fields": { "keyword": { "type": "keyword" } }
          }
        }
      },
      "doc_type": { "type": "keyword" }         // optional, e.g. "local_body"
    }
  }
}

